pragma solidity 0.7.6;
pragma abicoder v2;

contract Storage {
    uint256 public amountInCached;
    address public factoryV2;
    address public factoryV3;

    mapping(address => bool) public feeExcludeList;

    struct ExactInputSingleParams {
        address factoryAddress;
        address poolAddress;
        address tokenIn;
        address tokenOut;
        uint24 fee;
        address recipient;
        uint256 deadline;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 sqrtPriceLimitX96;
    }

    struct ExactInputParams {
        address[] factoryAddresses;
        address[] poolAddresses;
        bytes path;
        address recipient;
        uint256 deadline;
        uint256 amountIn;
        uint256 amountOutMinimum;
    }

    struct ExactOutputSingleParams {
        address factoryAddress;
        address poolAddress;
        address tokenIn;
        address tokenOut;
        uint24 fee;
        address recipient;
        uint256 deadline;
        uint256 amountOut;
        uint256 amountInMaximum;
        uint160 sqrtPriceLimitX96;
    }

    struct ExactOutputParams {
        address[] factoryAddresses;
        address[] poolAddresses;
        bytes path;
        address tokenIn;
        address recipient;
        uint256 deadline;
        uint256 amountOut;
        uint256 amountInMaximum;
    }

    struct ExactInputMixedParams {
        string[] routes;
        bytes path1;
        address factory1;
        address poolAddress1;
        bytes path2;
        address factory2;
        address poolAddress2;
        address recipient;
        uint256 deadline;
        uint256 amountIn;
        uint256 amountOutMinimum;
    }

    struct ExactOutputMixedParams {
        string[] routes;
        bytes path1;
        address factory1;
        address poolAddress1;
        bytes path2;
        address factory2;
        address poolAddress2;
        uint256 amountIn2; // only for v2-v3 router
        address recipient;
        uint256 deadline;
        uint256 amountOut;
        uint256 amountInMaximum;
    }

    struct SwapCallbackData {
        bytes path;
        address payer;
    }
}
","keccak256":"0x2eeee4a3fa580ad230f55ea4536890612737cf9688e0d3e09e830951d889b026","license":"MIT"},"contracts/SwapFee.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity 0.7.6;
pragma abicoder v2;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/SafeERC20.sol";
import "@openzeppelin/contracts/math/SafeMath.sol";
import "@openzeppelin/contracts/utils/SafeCast.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./interfaces/IUniswapV2Pair.sol";
import "./interfaces/IUniswapV3Pool.sol";
import "./interfaces/IUniswapV3SwapCallback.sol";
import "./interfaces/IWETH.sol";

import "./libs/Path.sol";
import "./libs/TickMath.sol";
import "./libs/UniswapV2Library.sol";
import "./libs/CallbackValidation.sol";
import "./Storage.sol";

contract SwapFee is Storage, Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    using SafeMath for uint;
    using Path for bytes;
    using SafeCast for uint256;

    // 管理员地址
    address private admin;

    // 手续费率 如需为 1% 则设置为 10000
    uint256 private feeRate;

    // 手续费分母
    uint256 private immutable FEE_DENOMINATOR = 1000000;

    // WETH
    address public immutable WETH;

    // 手续费收集地址
    address private feeCollector;

    event FeeCollected(
        address indexed token,
        address indexed payer,
        uint256 amount,
        uint256 timestamp
    );

    modifier checkDeadline(uint256 deadline) {
        require(block.timestamp <= deadline, "Transaction too old");
        _;
    }

    receive() external payable {}

    constructor(
        address _admin,
        address _feeCollector,
        uint256 _fee,
        address _weth
    ) {
        admin = _admin;
        feeCollector = _feeCollector;
        feeRate = _fee;
        WETH = _weth;
    }

    // function Swap(
    //     address pair,
    //     address token_in,
    //     address token_out,
    //     uint256 amount_in
    // ) public {
    //     require(msg.sender == owner, "Only owner can swap");
    //     // 获取手续费

    //     // 扣除手续费
    //     amount_in -= fee;

    //     //根据 pair 判断是 v2 还是 v3 ？ Swap by Uniswap

    //     // SwapBy Aerodrome

    //     // 调用swap
    //     IUniswapV2Router02(pair).swapExactTokensForTokens(
    //         amount_in,
    //         0,
    //         path,
    //         to,
    //         deadline
    //     );

    //     // 将手续费发送给管理员
    //     payable(admin).transfer(fee);
    // }

    // todo: 集成DEX
    // 1. uniswap V2   单跳 和 多跳
    // 2. uniswap V3   单挑 和 多跳

    // 3. Aerodrome

    // V2: Any swap, ExactIn single-hop - SupportingFeeOnTransferTokens
    function swapV2ExactIn(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOutMin,
        address poolAddress
    ) public payable nonReentrant returns (uint amountOut) {
        require(poolAddress != address(0), "SwapFee: invalid pool address");
        require(amountIn > 0, "SwapFee: amount_in invalid");

        // 处理原生代币输入
        bool nativeIn = _handleNativeTokenIn(tokenIn, amountIn);
        if (nativeIn) tokenIn = WETH;

        // 处理支付
        if (nativeIn) {
            pay(tokenIn, address(this), poolAddress, amountIn);
        } else {
            pay(tokenIn, msg.sender, poolAddress, amountIn);
        }

        // 检查是否为原生代币输出
        bool nativeOut = tokenOut == address(0);
        uint balanceBefore = nativeOut
            ? IERC20(WETH).balanceOf(address(this))
            : IERC20(tokenOut).balanceOf(msg.sender);

        // 执行交换
        amountOut = _executeV2Swap(
            poolAddress,
            tokenIn,
            nativeOut,
            balanceBefore
        );

        // 处理输出
        if (nativeOut) {
            amountOut = _handleNativeTokenOut(amountOut, msg.sender);
        } else {
            amountOut = IERC20(tokenOut).balanceOf(msg.sender).sub(
                balanceBefore
            );
        }

        require(amountOut >= amountOutMin, "SwapX: insufficient output amount");
    }

    // 处理原生代币输入
    function _handleNativeTokenIn(
        address tokenIn,
        uint256 amountIn
    ) internal returns (bool) {
        if (tokenIn != address(0)) return false;

        require(msg.value >= amountIn, "SwapFee: amount in and value mismatch");

        // 退还多余的 ETH
        uint amount = msg.value - amountIn;
        if (amount > 0) {
            (bool success, ) = address(msg.sender).call{value: amount}("");
            require(success, "SwapX: refund ETH error");
        }

        uint256 fee = takeFee(address(0), amountIn);
        amountIn = amountIn - fee;
        return true;
    }

    // 执行 V2 交换
    function _executeV2Swap(
        address poolAddress,
        address tokenIn,
        bool nativeOut,
        uint balanceBefore
    ) internal returns (uint amountOut) {
        IUniswapV2Pair pair = IUniswapV2Pair(poolAddress);
        address token0 = pair.token0();

        (uint reserve0, uint reserve1, ) = pair.getReserves();
        uint reserveInput = tokenIn == token0 ? reserve0 : reserve1;
        uint reserveOutput = tokenIn == token0 ? reserve1 : reserve0;

        uint amountInput = IERC20(tokenIn).balanceOf(address(pair)).sub(
            reserveInput
        );
        uint amountOutput = UniswapV2Library.getAmountOut(
            amountInput,
            reserveInput,
            reserveOutput,
            10
        );

        (uint amount0Out, uint amount1Out) = tokenIn == token0
            ? (uint(0), amountOutput)
            : (amountOutput, uint(0));

        address to = nativeOut ? address(this) : msg.sender;
        pair.swap(amount0Out, amount1Out, to, new bytes(0));

        return amountOutput;
    }

    // 处理原生代币输出
    function _handleNativeTokenOut(
        uint256 amountOut,
        address recipient
    ) internal returns (uint256) {
        amountOut = IERC20(WETH).balanceOf(address(this)).sub(amountOut);
        IWETH(WETH).withdraw(amountOut);
        uint256 fee = takeFee(address(0), amountOut);
        uint256 finalAmount = amountOut - fee;

        (bool success, ) = recipient.call{value: finalAmount}("");
        require(success, "SwapX: send ETH out error");

        return finalAmount;
    }

    // V3: ExactIn single-hop
    function swapV3ExactIn(
        ExactInputSingleParams memory params
    )
        external
        payable
        nonReentrant
        checkDeadline(params.deadline)
        returns (uint256 amountOut)
    {
        require(params.amountIn > 0, "SwapX: amount in is zero");

        if (params.tokenIn == WETH || params.tokenIn == address(0)) {
            params.tokenIn = WETH;
            require(
                msg.value >= params.amountIn,
                "SwapX: amount in and value mismatch"
            );
            // refund
            uint amount = msg.value - params.amountIn;
            if (amount > 0) {
                (bool success, ) = address(msg.sender).call{value: amount}("");
                require(success, "SwapX: refund ETH error");
            }
        }

        bool nativeOut = false;
        if (params.tokenOut == WETH) nativeOut = true;

        if (!nativeOut) {
            uint256 fee = takeFee(params.tokenIn, params.amountIn);
            params.amountIn = params.amountIn - fee;
        }

        // update factoryV3 globally, so as to pass callback verification
        factoryV3 = params.factoryAddress;
        amountOut = exactInputInternal(
            params.poolAddress,
            params.amountIn,
            nativeOut ? address(0) : params.recipient,
            params.sqrtPriceLimitX96,
            SwapCallbackData({
                path: abi.encodePacked(
                    params.tokenIn,
                    params.fee,
                    params.tokenOut
                ),
                payer: msg.sender
            })
        );

        require(
            amountOut >= params.amountOutMinimum,
            "SwapX: insufficient out amount"
        );

        if (nativeOut) {
            IWETH(WETH).withdraw(amountOut);
            uint256 fee = takeFee(address(0), amountOut);
            (bool success, ) = address(params.recipient).call{
                value: amountOut - fee
            }("");
            require(success, "SwapX: send ETH out error");
        }
    }

    //     /// V3: Performs a single exact input swap
    function exactInputInternal(
        address poolAddress,
        uint256 amountIn,
        address recipient,
        uint160 sqrtPriceLimitX96,
        SwapCallbackData memory data
    ) private returns (uint256 amountOut) {
        // allow swapping to the router address with address 0
        if (recipient == address(0)) recipient = address(this);

        (address tokenIn, address tokenOut, ) = data.path.decodeFirstPool();

        bool zeroForOne = tokenIn < tokenOut;

        (int256 amount0, int256 amount1) = IUniswapV3Pool(poolAddress).swap(
            recipient,
            zeroForOne,
            amountIn.toInt256(),
            sqrtPriceLimitX96 == 0
                ? (
                    zeroForOne
                        ? TickMath.MIN_SQRT_RATIO + 1
                        : TickMath.MAX_SQRT_RATIO - 1
                )
                : sqrtPriceLimitX96,
            abi.encode(data)
        );

        return uint256(-(zeroForOne ? amount1 : amount0));
    }

    // 处理代币支付逻辑
    function pay(
        address token,
        address payer,
        address recipient,
        uint256 value
    ) internal {
        if (token == WETH && address(this).balance >= value) {
            // pay with WETH
            IWETH(WETH).deposit{value: value}(); // wrap only what is needed to pay
            IWETH(WETH).transfer(recipient, value);
        } else if (payer == address(this)) {
            // pay with tokens already in the contract (for the exact input multihop case)
            //IERC20(token).safeTransfer(recipient, value);
            IERC20(token).transfer(recipient, value);
        } else {
            // pull payment
            //IERC20(token).safeTransferFrom(payer, recipient, value);
            IERC20(token).transferFrom(payer, recipient, value);
        }
    }

    // 收取手续费，并且将手续费发送给手续费收集地址
    // mapping(address => uint256) UserFeeRate 可以考虑设置不同地址的手续费率
    function takeFee(
        address tokenIn,
        uint256 amountIn
    ) internal returns (uint256) {
        uint256 fee = amountIn.mul(feeRate).div(FEE_DENOMINATOR);

        if (
            (tokenIn == address(0) || tokenIn == WETH) &&
            address(this).balance > fee
        ) {
            (bool success, ) = address(feeCollector).call{value: fee}("");
            require(success, "SwapX: take fee error");
        } else IERC20(tokenIn).safeTransferFrom(msg.sender, feeCollector, fee);

        emit FeeCollected(tokenIn, msg.sender, fee, block.timestamp);

        return fee;
    }

    // 设置手续费收集地址
    function setFeeCollector(address _feeCollector) public {
        require(msg.sender == admin, "Only admin can set fee collector");
        feeCollector = _feeCollector;
    }

    // 查询手续费收集地址
    function getFeeCollector() public view returns (address) {
        return feeCollector;
    }

    // 设置手续费率
    function setFeeRate(uint256 _fee) public {
        require(msg.sender == admin, "Only admin can set fee");
        feeRate = _fee;
    }

    function setAdmin(address _admin) public {
        require(msg.sender == admin, "Only admin can set admin");
        admin = _admin;
    }

    // 获取管理员地址
    function getAdmin() public view returns (address) {
        return admin;
    }

    // 获取手续费率
    function getFeeRate() public view returns (uint256) {
        return feeRate;
    }
}
